Rule.Source:
import sailpoint.object.Application;
import sailpoint.object.QueryOptions;
import sailpoint.object.Filter;
import sailpoint.connector.ConnectorFactory;
import sailpoint.connector.Connector;
import sailpoint.tools.GeneralException;
import java.util.List;
import java.util.ArrayList;
import java.util.Date;
import java.text.SimpleDateFormat;
import java.io.FileWriter;
import java.io.BufferedWriter;

SimpleDateFormat sdf     = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
SimpleDateFormat sdfFile = new SimpleDateFormat("yyyyMMdd_HHmmss");
String runDate = sdf.format(new Date());

QueryOptions qo = new QueryOptions();
qo.add(Filter.notnull("type"));
qo.add(Filter.ne("type", ""));
List apps = context.getObjects(Application.class, qo);

System.out.println("\n╔══════════════════════════════════════════════════════╗");
System.out.println("║       TEST DE CONNEXION — TOUS LES CONNECTEURS       ║");
System.out.println("║       " + runDate + "                       ║");
System.out.println("╚══════════════════════════════════════════════════════╝\n");

int pass = 0, fail = 0, skip = 0;

// Listes pour le rapport HTML
List successList = new ArrayList();
List failureList = new ArrayList();
List skippedList = new ArrayList();

// Structure simple : "name|type|ms|msg"
for (Object obj : apps) {
    Application app = (Application) obj;
    String name = app.getName();
    String type = app.getType();

    if (app.isDisabled()) {
        System.out.println("  [SKIPPED]  " + name + "  (" + type + ")  — désactivée");
        skippedList.add(name + "|" + type + "|0|désactivée");
        skip++;
        continue;
    }

    long t0 = System.currentTimeMillis();
    try {
        Connector c = ConnectorFactory.getConnector(app, null);
        if (c == null) {
            System.out.println("  [SKIPPED]  " + name + "  (" + type + ")  — ConnectorFactory null");
            skippedList.add(name + "|" + type + "|0|ConnectorFactory null");
            skip++;
            continue;
        }
        c.testConfiguration();
        long ms = System.currentTimeMillis() - t0;
        System.out.println("  [SUCCESS]  " + name + "  (" + type + ")  — " + ms + "ms");
        successList.add(name + "|" + type + "|" + ms + "|");
        pass++;
    } catch (Exception e) {
        long ms = System.currentTimeMillis() - t0;
        String msg = e.getMessage() != null ? e.getMessage() : e.getClass().getName();
        if (msg.length() > 200) msg = msg.substring(0, 200) + "...";
        // Échapper les caractères HTML dangereux
        msg = msg.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;");
        System.out.println("  [FAILURE]  " + name + "  (" + type + ")  — " + ms + "ms");
        System.out.println("             └─ " + msg);
        failureList.add(name + "|" + type + "|" + ms + "|" + msg);
        fail++;
    }
}

System.out.println("\n══════════════════════════════════════════════════════");
System.out.println("  RÉSUMÉ  →  SUCCESS: " + pass + "   FAILURE: " + fail + "   SKIPPED: " + skip);
System.out.println("  Total : " + apps.size() + " applications");
System.out.println("══════════════════════════════════════════════════════\n");

// ─────────────────────────────────────────────
// GÉNÉRATION DU RAPPORT HTML
// ─────────────────────────────────────────────
String htmlPath = "/tmp/connector-report-" + sdfFile.format(new Date()) + ".html";

StringBuilder rows = new StringBuilder();

// Lignes SUCCESS
for (Object entry : successList) {
    String[] parts = ((String) entry).split("\\|", -1);
    String n  = parts.length > 0 ? parts[0] : "";
    String t  = parts.length > 1 ? parts[1] : "";
    String ms = parts.length > 2 ? parts[2] : "";
    rows.append("<tr class=\"row-success\">");
    rows.append("<td><span class=\"badge badge-success\">SUCCESS</span></td>");
    rows.append("<td class=\"app-name\">" + n + "</td>");
    rows.append("<td class=\"type-cell\">" + t + "</td>");
    rows.append("<td class=\"ms-cell\">" + ms + " ms</td>");
    rows.append("<td class=\"msg-cell\">—</td>");
    rows.append("</tr>\n");
}

// Lignes FAILURE
for (Object entry : failureList) {
    String[] parts = ((String) entry).split("\\|", -1);
    String n   = parts.length > 0 ? parts[0] : "";
    String t   = parts.length > 1 ? parts[1] : "";
    String ms  = parts.length > 2 ? parts[2] : "";
    String msg = parts.length > 3 ? parts[3] : "";
    rows.append("<tr class=\"row-failure\">");
    rows.append("<td><span class=\"badge badge-failure\">FAILURE</span></td>");
    rows.append("<td class=\"app-name\">" + n + "</td>");
    rows.append("<td class=\"type-cell\">" + t + "</td>");
    rows.append("<td class=\"ms-cell\">" + ms + " ms</td>");
    rows.append("<td class=\"msg-cell\">" + msg + "</td>");
    rows.append("</tr>\n");
}

// Lignes SKIPPED
for (Object entry : skippedList) {
    String[] parts = ((String) entry).split("\\|", -1);
    String n   = parts.length > 0 ? parts[0] : "";
    String t   = parts.length > 1 ? parts[1] : "";
    String msg = parts.length > 3 ? parts[3] : "";
    rows.append("<tr class=\"row-skipped\">");
    rows.append("<td><span class=\"badge badge-skipped\">SKIPPED</span></td>");
    rows.append("<td class=\"app-name\">" + n + "</td>");
    rows.append("<td class=\"type-cell\">" + t + "</td>");
    rows.append("<td class=\"ms-cell\">—</td>");
    rows.append("<td class=\"msg-cell\">" + msg + "</td>");
    rows.append("</tr>\n");
}

int total = apps.size();
int failPct  = total > 0 ? (int)((fail  * 100.0) / total) : 0;
int passPct  = total > 0 ? (int)((pass  * 100.0) / total) : 0;
int skipPct  = total > 0 ? (int)((skip  * 100.0) / total) : 0;

String html = "<!DOCTYPE html>\n"
+ "<html lang=\"fr\">\n"
+ "<head>\n"
+ "<meta charset=\"UTF-8\">\n"
+ "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n"
+ "<title>IIQ Connector Health Report — " + runDate + "</title>\n"
+ "<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n"
+ "<link href=\"https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;600;700&family=Syne:wght@400;600;800&display=swap\" rel=\"stylesheet\">\n"
+ "<style>\n"
+ "  :root {\n"
+ "    --bg:       #0a0c10;\n"
+ "    --surface:  #10141c;\n"
+ "    --border:   #1e2535;\n"
+ "    --success:  #00e5a0;\n"
+ "    --failure:  #ff3d5a;\n"
+ "    --skipped:  #ffa040;\n"
+ "    --muted:    #4a5568;\n"
+ "    --text:     #d0d8e8;\n"
+ "    --accent:   #5b8aff;\n"
+ "  }\n"
+ "  * { box-sizing: border-box; margin: 0; padding: 0; }\n"
+ "  body {\n"
+ "    background: var(--bg);\n"
+ "    color: var(--text);\n"
+ "    font-family: 'Syne', sans-serif;\n"
+ "    min-height: 100vh;\n"
+ "  }\n"
+ "  /* ── HEADER ── */\n"
+ "  .header {\n"
+ "    border-bottom: 1px solid var(--border);\n"
+ "    padding: 36px 48px 28px;\n"
+ "    display: flex;\n"
+ "    justify-content: space-between;\n"
+ "    align-items: flex-end;\n"
+ "    background: linear-gradient(135deg, #0d1220 0%, #0a0c10 60%);\n"
+ "  }\n"
+ "  .header-left .label {\n"
+ "    font-family: 'JetBrains Mono', monospace;\n"
+ "    font-size: 11px;\n"
+ "    letter-spacing: 0.18em;\n"
+ "    color: var(--accent);\n"
+ "    text-transform: uppercase;\n"
+ "    margin-bottom: 8px;\n"
+ "  }\n"
+ "  .header-left h1 {\n"
+ "    font-size: 28px;\n"
+ "    font-weight: 800;\n"
+ "    letter-spacing: -0.02em;\n"
+ "    color: #fff;\n"
+ "    line-height: 1;\n"
+ "  }\n"
+ "  .header-left h1 span { color: var(--accent); }\n"
+ "  .header-right {\n"
+ "    font-family: 'JetBrains Mono', monospace;\n"
+ "    font-size: 12px;\n"
+ "    color: var(--muted);\n"
+ "    text-align: right;\n"
+ "    line-height: 1.7;\n"
+ "  }\n"
+ "  /* ── SCOREBOARD ── */\n"
+ "  .scoreboard {\n"
+ "    display: grid;\n"
+ "    grid-template-columns: repeat(4, 1fr);\n"
+ "    gap: 1px;\n"
+ "    background: var(--border);\n"
+ "    border-bottom: 1px solid var(--border);\n"
+ "  }\n"
+ "  .score-card {\n"
+ "    background: var(--surface);\n"
+ "    padding: 28px 32px;\n"
+ "    position: relative;\n"
+ "    overflow: hidden;\n"
+ "  }\n"
+ "  .score-card::before {\n"
+ "    content: '';\n"
+ "    position: absolute;\n"
+ "    top: 0; left: 0; right: 0;\n"
+ "    height: 3px;\n"
+ "  }\n"
+ "  .score-card.c-total::before  { background: var(--accent); }\n"
+ "  .score-card.c-success::before{ background: var(--success); }\n"
+ "  .score-card.c-failure::before{ background: var(--failure); }\n"
+ "  .score-card.c-skipped::before{ background: var(--skipped); }\n"
+ "  .score-label {\n"
+ "    font-family: 'JetBrains Mono', monospace;\n"
+ "    font-size: 10px;\n"
+ "    letter-spacing: 0.14em;\n"
+ "    text-transform: uppercase;\n"
+ "    color: var(--muted);\n"
+ "    margin-bottom: 10px;\n"
+ "  }\n"
+ "  .score-value {\n"
+ "    font-size: 48px;\n"
+ "    font-weight: 800;\n"
+ "    line-height: 1;\n"
+ "    letter-spacing: -0.03em;\n"
+ "  }\n"
+ "  .c-total  .score-value { color: var(--accent); }\n"
+ "  .c-success .score-value{ color: var(--success); }\n"
+ "  .c-failure .score-value{ color: var(--failure); }\n"
+ "  .c-skipped .score-value{ color: var(--skipped); }\n"
+ "  .score-pct {\n"
+ "    font-family: 'JetBrains Mono', monospace;\n"
+ "    font-size: 12px;\n"
+ "    color: var(--muted);\n"
+ "    margin-top: 6px;\n"
+ "  }\n"
+ "  /* ── FILTER BAR ── */\n"
+ "  .filter-bar {\n"
+ "    display: flex;\n"
+ "    gap: 8px;\n"
+ "    padding: 20px 48px;\n"
+ "    border-bottom: 1px solid var(--border);\n"
+ "    background: var(--surface);\n"
+ "  }\n"
+ "  .filter-btn {\n"
+ "    font-family: 'JetBrains Mono', monospace;\n"
+ "    font-size: 11px;\n"
+ "    letter-spacing: 0.1em;\n"
+ "    text-transform: uppercase;\n"
+ "    padding: 6px 16px;\n"
+ "    border-radius: 4px;\n"
+ "    border: 1px solid var(--border);\n"
+ "    background: transparent;\n"
+ "    color: var(--muted);\n"
+ "    cursor: pointer;\n"
+ "    transition: all 0.15s;\n"
+ "  }\n"
+ "  .filter-btn:hover, .filter-btn.active {\n"
+ "    background: var(--border);\n"
+ "    color: var(--text);\n"
+ "  }\n"
+ "  .filter-btn.f-success.active { border-color: var(--success); color: var(--success); }\n"
+ "  .filter-btn.f-failure.active { border-color: var(--failure); color: var(--failure); }\n"
+ "  .filter-btn.f-skipped.active { border-color: var(--skipped); color: var(--skipped); }\n"
+ "  /* ── TABLE ── */\n"
+ "  .table-wrap {\n"
+ "    padding: 0 48px 48px;\n"
+ "    overflow-x: auto;\n"
+ "  }\n"
+ "  table {\n"
+ "    width: 100%;\n"
+ "    border-collapse: collapse;\n"
+ "    margin-top: 0;\n"
+ "  }\n"
+ "  thead tr {\n"
+ "    border-bottom: 1px solid var(--border);\n"
+ "  }\n"
+ "  thead th {\n"
+ "    font-family: 'JetBrains Mono', monospace;\n"
+ "    font-size: 10px;\n"
+ "    letter-spacing: 0.14em;\n"
+ "    text-transform: uppercase;\n"
+ "    color: var(--muted);\n"
+ "    padding: 16px 14px;\n"
+ "    text-align: left;\n"
+ "    font-weight: 600;\n"
+ "  }\n"
+ "  tbody tr {\n"
+ "    border-bottom: 1px solid rgba(30,37,53,0.6);\n"
+ "    transition: background 0.12s;\n"
+ "  }\n"
+ "  tbody tr:hover { background: rgba(255,255,255,0.03); }\n"
+ "  tbody td {\n"
+ "    padding: 13px 14px;\n"
+ "    font-size: 13.5px;\n"
+ "    vertical-align: middle;\n"
+ "  }\n"
+ "  .app-name {\n"
+ "    font-weight: 600;\n"
+ "    color: #fff;\n"
+ "    font-size: 13px;\n"
+ "  }\n"
+ "  .type-cell {\n"
+ "    font-family: 'JetBrains Mono', monospace;\n"
+ "    font-size: 11.5px;\n"
+ "    color: var(--muted);\n"
+ "  }\n"
+ "  .ms-cell {\n"
+ "    font-family: 'JetBrains Mono', monospace;\n"
+ "    font-size: 12px;\n"
+ "    color: var(--muted);\n"
+ "    white-space: nowrap;\n"
+ "  }\n"
+ "  .msg-cell {\n"
+ "    font-family: 'JetBrains Mono', monospace;\n"
+ "    font-size: 11px;\n"
+ "    color: #8892a4;\n"
+ "    max-width: 420px;\n"
+ "    word-break: break-word;\n"
+ "  }\n"
+ "  /* ── BADGES ── */\n"
+ "  .badge {\n"
+ "    font-family: 'JetBrains Mono', monospace;\n"
+ "    font-size: 10px;\n"
+ "    font-weight: 700;\n"
+ "    letter-spacing: 0.1em;\n"
+ "    padding: 3px 9px;\n"
+ "    border-radius: 3px;\n"
+ "    display: inline-block;\n"
+ "    white-space: nowrap;\n"
+ "  }\n"
+ "  .badge-success { background: rgba(0,229,160,0.12); color: var(--success); border: 1px solid rgba(0,229,160,0.25); }\n"
+ "  .badge-failure { background: rgba(255,61,90,0.12);  color: var(--failure); border: 1px solid rgba(255,61,90,0.25); }\n"
+ "  .badge-skipped { background: rgba(255,160,64,0.12); color: var(--skipped); border: 1px solid rgba(255,160,64,0.25); }\n"
+ "  /* ── ROW STATES ── */\n"
+ "  .row-failure td.app-name { color: var(--failure); }\n"
+ "  .row-skipped td.app-name { color: var(--skipped); }\n"
+ "  .row-success td.app-name { color: var(--success); }\n"
+ "  /* ── FOOTER ── */\n"
+ "  .footer {\n"
+ "    border-top: 1px solid var(--border);\n"
+ "    padding: 20px 48px;\n"
+ "    font-family: 'JetBrains Mono', monospace;\n"
+ "    font-size: 11px;\n"
+ "    color: var(--muted);\n"
+ "    display: flex;\n"
+ "    justify-content: space-between;\n"
+ "  }\n"
+ "</style>\n"
+ "</head>\n"
+ "<body>\n"
+ "  <!-- HEADER -->\n"
+ "  <div class=\"header\">\n"
+ "    <div class=\"header-left\">\n"
+ "      <div class=\"label\">SailPoint IdentityIQ 8.4 · Connector Health</div>\n"
+ "      <h1>IIQ <span>Connector</span> Report</h1>\n"
+ "    </div>\n"
+ "    <div class=\"header-right\">\n"
+ "      <div>" + runDate + "</div>\n"
+ "      <div>Environnement : PROD</div>\n"
+ "    </div>\n"
+ "  </div>\n"
+ "\n"
+ "  <!-- SCOREBOARD -->\n"
+ "  <div class=\"scoreboard\">\n"
+ "    <div class=\"score-card c-total\">\n"
+ "      <div class=\"score-label\">Total</div>\n"
+ "      <div class=\"score-value\">" + total + "</div>\n"
+ "      <div class=\"score-pct\">applications testées</div>\n"
+ "    </div>\n"
+ "    <div class=\"score-card c-success\">\n"
+ "      <div class=\"score-label\">Success</div>\n"
+ "      <div class=\"score-value\">" + pass + "</div>\n"
+ "      <div class=\"score-pct\">" + passPct + "% du total</div>\n"
+ "    </div>\n"
+ "    <div class=\"score-card c-failure\">\n"
+ "      <div class=\"score-label\">Failure</div>\n"
+ "      <div class=\"score-value\">" + fail + "</div>\n"
+ "      <div class=\"score-pct\">" + failPct + "% du total</div>\n"
+ "    </div>\n"
+ "    <div class=\"score-card c-skipped\">\n"
+ "      <div class=\"score-label\">Skipped</div>\n"
+ "      <div class=\"score-value\">" + skip + "</div>\n"
+ "      <div class=\"score-pct\">" + skipPct + "% du total</div>\n"
+ "    </div>\n"
+ "  </div>\n"
+ "\n"
+ "  <!-- FILTER BAR -->\n"
+ "  <div class=\"filter-bar\">\n"
+ "    <button class=\"filter-btn active\" onclick=\"filterTable('all', this)\">Tous</button>\n"
+ "    <button class=\"filter-btn f-success\" onclick=\"filterTable('row-success', this)\">Success</button>\n"
+ "    <button class=\"filter-btn f-failure\" onclick=\"filterTable('row-failure', this)\">Failure</button>\n"
+ "    <button class=\"filter-btn f-skipped\" onclick=\"filterTable('row-skipped', this)\">Skipped</button>\n"
+ "  </div>\n"
+ "\n"
+ "  <!-- TABLE -->\n"
+ "  <div class=\"table-wrap\">\n"
+ "    <table id=\"connTable\">\n"
+ "      <thead>\n"
+ "        <tr>\n"
+ "          <th>Statut</th>\n"
+ "          <th>Application</th>\n"
+ "          <th>Type</th>\n"
+ "          <th>Durée</th>\n"
+ "          <th>Message</th>\n"
+ "        </tr>\n"
+ "      </thead>\n"
+ "      <tbody id=\"tableBody\">\n"
+ rows.toString()
+ "      </tbody>\n"
+ "    </table>\n"
+ "  </div>\n"
+ "\n"
+ "  <!-- FOOTER -->\n"
+ "  <div class=\"footer\">\n"
+ "    <span>rule \"Test All Connectors\" · IIQ 8.4p3</span>\n"
+ "    <span>SUCCESS " + pass + " · FAILURE " + fail + " · SKIPPED " + skip + "</span>\n"
+ "  </div>\n"
+ "\n"
+ "<script>\n"
+ "function filterTable(cls, btn) {\n"
+ "  document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));\n"
+ "  btn.classList.add('active');\n"
+ "  const rows = document.querySelectorAll('#tableBody tr');\n"
+ "  rows.forEach(r => {\n"
+ "    r.style.display = (cls === 'all' || r.classList.contains(cls)) ? '' : 'none';\n"
+ "  });\n"
+ "}\n"
+ "</script>\n"
+ "</body>\n"
+ "</html>\n";

// Écriture du fichier
try {
    BufferedWriter bw = new BufferedWriter(new FileWriter(htmlPath));
    bw.write(html);
    bw.close();
    System.out.println("  [HTML]  Rapport généré → " + htmlPath);
} catch (Exception ioe) {
    System.out.println("  [WARN]  Impossible d'écrire le rapport HTML : " + ioe.getMessage());
}

return "Terminé — SUCCESS: " + pass + " / FAILURE: " + fail + " / SKIPPED: " + skip
     + " | HTML → " + htmlPath;
